import React, { useEffect, useState } from 'react';
import {
  Box,
  Button,
  Chip,
  InputAdornment,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import usePageQuery from '../../core/hooks/usePageQuery';
import { Table } from '@tanstack/react-table';
import ReactTable from '../../components/Table/ReactTable';
import PosTablePagination from '../../components/Table/PosTablePagination';
import { useDeleteBranchManageMutation } from '../posApi';
import { useTranslation } from 'react-i18next';
import { IBranchDetailsData } from '../../core/Interface/branch.interface';
import useBranchList from './useBranchList';
import AnimatedPage from '../../layouts/AnimatedPage';
import AddIcon from '@mui/icons-material/Add';
import AccountBalanceOutlinedIcon from '@mui/icons-material/AccountBalanceOutlined';
import SearchIcon from '@mui/icons-material/Search';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import { useNotifier } from '../../core/Notifier';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import NewBranch from './Components/NewBranch';
import ViewBranchDetails from './Components/ViewBranchDetails';
import { HEADER_GRADIENT } from '../../theme/appColors';

const BranchList = () => {
  const { setPage } = usePageQuery();
  const { t } = useTranslation(['common', 'branchManage', 'usermanage']);
  const [branchToDelete, setBranchToDelete] = useState<IBranchDetailsData | null>(null);
  const { showErrorMessage, showMessage } = useNotifier();
  const { userHasRight } = useUser();
  const [branchData, setBranchData] = React.useState<IBranchDetailsData | undefined>();
  const [openAddBranch, setOpenAddBranch] = useState(false);
  const [openDeleteBranch, setOpenDeleteBranch] = useState(false);
  const [branchNameToDelete, setBranchNameToDelete] = useState('');
  const [branchDetails, setBranchDetails] = React.useState<IBranchDetailsData>();
  const [openViewBranch, setOpenViewBranch] = useState(false);
  const [localSearch, setLocalSearch] = useState('');

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  const handleEdit = (data: IBranchDetailsData) => {
    setBranchData(data);
    setOpenAddBranch(true);
  };

  const [deleteBranch] = useDeleteBranchManageMutation();

  const handleDelete = (data: IBranchDetailsData) => {
    setBranchToDelete(data);
    setBranchData(data);
    setBranchNameToDelete(data.name);
    setOpenDeleteBranch(true);
  };

  const handleConfirmDelete = async () => {
    if (!branchToDelete) return;
    try {
      const response = await deleteBranch(branchToDelete.id.toString()).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteBranch(false);
        setBranchToDelete(null);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const viewBranchDetailsPopUp = (id: string) => {
    const selected = table.getRowModel().rows.map((r) => r.original).find((u) => u.id === id);
    if (selected) { setBranchDetails(selected); setOpenViewBranch(true); }
  };

  const { table, isLoading, totalCount, setSearchQuery } = useBranchList(
    handleEdit, handleDelete, viewBranchDetailsPopUp
  );

  useEffect(() => {
    if (!isLoading && table.getState().pagination.pageIndex !== 0 && table.getRowModel().rows.length === 0) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  return (
    <AnimatedPage>
      <Box data-testid="branch-management">
        {/* Hero Panel */}
        <Paper
          elevation={0}
          sx={{ background: HEADER_GRADIENT, borderRadius: 2, mb: 2, overflow: 'hidden' }}
        >
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexWrap: 'wrap',
              gap: 2,
              justifyContent: 'space-between',
              px: 3,
              py: 2,
            }}
          >
            {/* Title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: 'rgba(255,255,255,0.15)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <AccountBalanceOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>
                  Branch Management
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
                  All branches
                </Typography>
              </Box>
              {totalCount > 0 && (
                <Chip
                  label={`${totalCount} records`}
                  size="small"
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: '#fff',
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
              )}
            </Box>

            {/* Search + Add */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: '10px' }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setLocalSearch(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') setSearchQuery(localSearch); }}
                placeholder="Search by name or code…"
                size="small"
                sx={{
                  minWidth: 260,
                  '& .MuiOutlinedInput-root': {
                    background: 'rgba(255,255,255,0.12)',
                    borderRadius: '8px',
                    color: '#fff',
                    height: 40,
                    '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                  },
                }}
                value={localSearch}
                variant="outlined"
              />
              <Button
                onClick={() => setSearchQuery(localSearch)}
                sx={{
                  background: 'rgba(255,255,255,0.15)',
                  border: '1px solid rgba(255,255,255,0.3)',
                  borderRadius: '8px',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 600,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'rgba(255,255,255,0.25)' },
                }}
                variant="contained"
              >
                {t('common:search')}
              </Button>

              {userHasRight(Privileges.BranchManageAdd) && (
                <Button
                  onClick={() => { setBranchData(undefined); setOpenAddBranch(true); }}
                  startIcon={<AddIcon />}
                  sx={{
                    background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                    borderRadius: '8px',
                    boxShadow: '0 4px 14px rgba(37,99,235,0.35)',
                    color: '#fff',
                    flexShrink: 0,
                    fontWeight: 700,
                    height: 40,
                    px: 2.5,
                    '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                  }}
                  variant="contained"
                >
                  Branch
                </Button>
              )}
            </Box>
          </Box>
        </Paper>

        {/* Table */}
        <Paper
          elevation={0}
          sx={{ border: '1px solid #E2E8F0', borderRadius: 2, overflow: 'hidden' }}
        >
          <Box sx={{ maxWidth: '100%', minHeight: 480, overflow: 'auto' }}>
            <ReactTable isLoading={isLoading} {...(table as Table<object>)} />
          </Box>

          {table.getTotalSize() !== 0 && (
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          )}
        </Paper>

        {openAddBranch && (
          <NewBranch
            branchdata={branchData}
            handleCloseDialog={() => setOpenAddBranch(false)}
            openModel={openAddBranch}
            title={`${branchData ? t('branchManage:edit') : t('usermanage:addNewBranch')}`}
          />
        )}

        {openDeleteBranch && (
          <DeletePopup
            content={`${t('branchManage:confirmMessage')} "${branchNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteBranch(false)}
            onConfirm={handleConfirmDelete}
            open={openDeleteBranch}
            title={t('branchManage:deleteBranch')}
          />
        )}

        {openViewBranch && branchDetails && (
          <ViewBranchDetails
            data={branchDetails}
            open={openViewBranch}
            setOpen={setOpenViewBranch}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default BranchList;
