/* eslint-disable react/jsx-sort-props */
import React from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
  useMediaQuery,
  Avatar,
} from '@mui/material';
import { IBranchDetailsData } from '../../../core/Interface/branch.interface';
import { theme } from '../../../theme';
import { useTranslation } from 'react-i18next';
import { formatDateTime } from '../../../core/utils';

interface ViewBranchListDataProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  data?: IBranchDetailsData;
}

const ViewBranchDetails: React.FC<ViewBranchListDataProps> = ({
  open,
  setOpen,
  data,
}) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { t } = useTranslation(['branchManage', 'category']);
  const handleCloseDialog = () => {
    setOpen(false);
  };

  return (
    <Dialog
      aria-labelledby="branch-list-data-title"
      fullScreen={isMobile}
      fullWidth
      maxWidth="sm"
      onClose={handleCloseDialog}
      open={open}
    >
      <DialogTitle
        id="branch-list-data-title"
        sx={{
          fontWeight: 600,
          background: '#CFD8DC',
          borderRadius: 1,
          padding: '16px 24px',
        }}
      >
        Branch Details
      </DialogTitle>
      <DialogContent
        sx={{
          display: 'grid',
          gridTemplateColumns: 'auto 10px auto',
          gap: 1,
          alignItems: 'center',
          padding: '10px 20px',
          mt: 2,
        }}
      >
        {data ? (
          <>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              <strong>{t('category:title.code')}</strong>
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ fontSize: 18, textAlign: 'center' }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              color="text.secondary"
              variant="body1"
            >
              <strong>{data.code}</strong>
            </Typography>

            <Typography
              color="text.secondary"
              sx={{ fontSize: 18 }}
              variant="body1"
            >
              {t('category:title.name')}
            </Typography>
            <Typography
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
              variant="body1"
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.name}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:mobile')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.mobile}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:email')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.email}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:reloadLoginMobile')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.reloadLoginMobile}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:headerText1')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.headerText1}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:headerText2')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.headerText2}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:headerText3')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.headerText3}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:footerText1')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.footerText1}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:footerText2')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.footerText2}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:footerText3')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.footerText3}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:printPaperSize')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.printPaperSize}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:noticeText')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.noticeText}
            </Typography>

            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {t('branchManage:totalCount')}
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ textAlign: 'center', fontSize: 18 }}
            >
              :
            </Typography>
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ fontSize: 18 }}
            >
              {data.totalCount}
            </Typography>

            {data.createdBy && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('branchManage:createdBy')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {data.createdBy}
                </Typography>
              </>
            )}
            {data.updatedBy && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('branchManage:updatedBy')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {data.updatedBy}
                </Typography>
              </>
            )}
            {data.createdDate && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('branchManage:createdDate')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {formatDateTime(new Date(data.createdDate))}
                </Typography>
              </>
            )}
            {data.updatedDate && (
              <>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('branchManage:updatedDate')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {formatDateTime(new Date(data.updatedDate))}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ fontSize: 18 }}
                >
                  {t('branchManage:logo')}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ textAlign: 'center', fontSize: 18 }}
                >
                  :
                </Typography>
                <Avatar
                  src={data.logo}
                  alt={data.name}
                  sx={{ width: 80, height: 80, borderRadius: '50%' }}
                />
              </>
            )}
          </>
        ) : (
          <Typography variant="body1">No Branch data available</Typography>
        )}
      </DialogContent>
      <DialogActions sx={{ padding: '16px 24px' }}>
        <Button
          onClick={handleCloseDialog}
          color="primary"
          sx={{
            width: 200,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ViewBranchDetails;
